import React from 'react';
import { calculateStats, getCyberpunkColors } from './ComplaintTrackingChart';

const SummaryStats = ({ analyzedData }) => {
  // Exit early if no data
  if (!analyzedData || !analyzedData.chunks || analyzedData.chunks.length === 0) {
    return (
      <div className="flex flex-col items-center w-full p-4 rounded-lg shadow-2xl border border-green-500" style={{
        background: 'linear-gradient(135deg, #0d0208 0%, #0f100f 100%)',
        boxShadow: '0 0 20px #008f11'
      }}>
        <h2 className="text-2xl font-bold mb-6 font-mono uppercase tracking-widest" style={{color: '#00ff41'}}>ANALYSIS SUMMARY // NO DATA AVAILABLE</h2>
      </div>
    );
  }

  // Get cyberpunk colors and calculate stats from the analyzedData
  const colors = getCyberpunkColors();
  const { averagePercentage, peakWindow, runtime, data } = calculateStats(analyzedData.chunks);

  return (
    <div className="flex flex-col items-center w-full p-3 rounded-lg shadow-2xl border border-green-500" style={{
      background: `linear-gradient(135deg, ${colors.dark.base} 0%, ${colors.dark.secondary} 100%)`,
      boxShadow: `0 0 20px ${colors.neon.darkGreen}`
    }}>
      <h2 className="text-lg font-bold mb-3 font-mono uppercase tracking-widest" style={{color: colors.neon.green}}>ANALYSIS SUMMARY</h2>

      {/* SYSTEM DIAGNOSTICS SECTION */}
      <div className="w-full bg-gray-900 p-2 rounded-lg shadow-lg mb-3 border border-green-500" style={{
        background: 'rgba(0, 20, 0, 0.7)', 
        boxShadow: `0 0 15px ${colors.neon.darkGreen}`
      }}>
        <h3 className="text-sm font-mono font-semibold mb-2 text-center uppercase tracking-wider" style={{color: colors.neon.green}}>// SYSTEM DIAGNOSTICS //</h3>
        <div className="grid grid-cols-3 gap-2">
          <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 flex flex-col items-center" style={{boxShadow: `0 0 10px ${colors.neon.darkGreen}`}}>
            <span className="text-xs font-mono text-gray-400 uppercase">CMPLNT.RATIO</span>
            <span className="text-xl font-bold font-mono" style={{color: colors.neon.green}}>{averagePercentage}%</span>
          </div>
          <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 flex flex-col items-center" style={{boxShadow: `0 0 10px ${colors.neon.darkGreen}`}}>
            <span className="text-xs font-mono text-gray-400 uppercase">PEAK.ALARM</span>
            <span className="text-xl font-bold font-mono" style={{color: colors.neon.green}}>{peakWindow}</span>
          </div>
          <div className="bg-black p-2 rounded-lg shadow-lg border border-green-500 flex flex-col items-center" style={{boxShadow: `0 0 10px ${colors.neon.darkGreen}`}}>
            <span className="text-xs font-mono text-gray-400 uppercase">RUNTIME</span>
            <span className="text-xl font-bold font-mono" style={{color: colors.neon.green}}>{runtime}</span>
          </div>
        </div>
      </div>

      {/* CONVERSATION DATASTREAM TABLE */}
      <div className="w-full">
        <h3 className="text-sm font-mono font-semibold mb-2 text-center uppercase tracking-wider" style={{color: colors.neon.green}}>// CONVERSATION DATASTREAM //</h3>
        <div style={{boxShadow: `0 0 15px ${colors.neon.darkGreen}`}}>
          <table className="min-w-full bg-black border border-green-500">
            <thead>
              <tr className="bg-gray-900 border-b border-green-500">
                <th className="p-1 border-r border-green-500 font-mono text-xs" style={{color: colors.neon.green}}>SEQ</th>
                <th className="p-1 border-r border-green-500 font-mono text-xs" style={{color: colors.neon.green}}>TIME</th>
                <th className="p-1 border-r border-green-500 font-mono text-xs" style={{color: colors.neon.green}}>STATUS</th>
                <th className="p-1 font-mono text-xs" style={{color: colors.neon.green}}>DATA</th>
              </tr>
            </thead>
            <tbody style={{fontFamily: 'monospace'}}>
              {data.map((item, index) => (
                <tr key={index} className={`border-b border-green-900 ${index % 2 === 0 ? 'bg-black' : 'bg-gray-900'}`}>
                  <td className="p-1 border-r border-green-900 font-mono font-medium text-xs" style={{color: colors.neon.green}}>{item.window}</td>
                  <td className="p-1 border-r border-green-900 font-mono text-xs" style={{color: colors.neon.darkGreen}}>{item.timeRange}</td>
                  <td className="p-1 border-r border-green-900">
                    <span className={`px-1 py-0 text-xs font-semibold font-mono
                      ${item.complaintLevel === 0 ? 'bg-black text-green-400 border border-green-500' : 
                        item.complaintLevel === 1 ? 'bg-black text-yellow-400 border border-yellow-500' : 
                        'bg-black text-red-400 border border-red-500'}`}
                      style={{
                        boxShadow: item.complaintLevel === 0 ? `0 0 5px ${colors.neon.green}` : 
                                  item.complaintLevel === 1 ? `0 0 5px ${colors.neon.yellow}` : 
                                  `0 0 5px red`
                      }}>
                      {item.complaintLevel === 0 ? 'STABLE' : 
                       item.complaintLevel === 1 ? 'CAUTION' : 'ALERT'}
                    </span>
                  </td>
                  <td className="p-1 font-mono text-xs" style={{color: colors.neon.darkGreen}}>{item.description}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="w-full text-center mt-3 font-mono text-xs" style={{color: colors.neon.darkGreen}}>
        <p>CORP//MAINFRAME ACCESS [v3.5.2] © 2025 [RESTRICTED]</p>
      </div>
    </div>
  );
};

export default SummaryStats;
